[
  {
    "title": "跨來源架構",
    "body": "前端與 API 位於不同來源時，瀏覽器會阻擋跨來源讀取；CORS 讓伺服器授權這類讀取。",
    "examples": [
      "前端：https://app.example\nAPI：https://api.example"
    ],
    "lines": [7, 8]
  },
  {
    "title": "伺服器以標頭授權",
    "body": "伺服器在回應加入標頭，列出允許的來源；瀏覽器確認符合後，才把結果交給網頁。",
    "examples": [
      "Access-Control-Allow-Origin: https://app.example"
    ],
    "lines": [10, 11]
  },
  {
    "title": "權限決定權在伺服器",
    "body": "是否允許跨來源讀取由伺服器決定，發出請求的網頁不能自行宣稱獲得權限。",
    "examples": [
      "惡意網站無法僅靠加入自訂標頭，就取得 API 回應內容。"
    ],
    "lines": [13, 13]
  },
  {
    "title": "憑證請求不能用萬用字元",
    "body": "跨來源請求若帶上憑證，伺服器必須明確指定允許的來源，不得使用萬用字元。",
    "examples": [
      "帶 Cookie 的請求應回傳 Access-Control-Allow-Origin: https://app.example，而不是 *。"
    ],
    "lines": [15, 15]
  }
]
